import json
from datetime import datetime

data=json.load(open('/app/benchmark/source_data.json'))

def parse_ym(s):
    return datetime.strptime(s,'%Y-%m')

def mins(ds):
    return min(parse_ym(d['date']) for d in ds)

def maxs(ds):
    return max(parse_ym(d['date']) for d in ds)

for k in ['research_milestones','industry_milestones','regulation_milestones']:
    ds=data[k]['data']
    print(k, len(ds), mins(ds).date(), maxs(ds).date())

# compute lag examples
from dateutil.relativedelta import relativedelta

def diff_years(a,b):
    rd=relativedelta(b,a)
    return rd.years + rd.months/12

def find(label_key, label_contains):
    for k in ['research_milestones','industry_milestones','regulation_milestones']:
        for d in data[k]['data']:
            if label_contains in d['label']:
                return k,d
    return None

trans=find('label','Transformer architecture')[1]
chat=find('label','ChatGPT launches')[1]
eu=find('label','EU AI Act enacted')[1]

A=parse_ym(trans['date']);B=parse_ym(chat['date']);C=parse_ym(eu['date'])
print('Transformer->ChatGPT years', diff_years(A,B))
print('ChatGPT->EU enacted years', diff_years(B,C))

# investments around chatgpt
inv={d['year']:d['investment'] for d in data['ai_investment']['data']}
print('inv 2022',inv[2022],'2024',inv[2024])
